import json
import urllib.request
import urllib.parse
import boto3
import socket
import time

# Lambda function invoked by Step Functions workflow
# Fetches metadata from user-provided webhook URLs for validation

def resolve_and_check(url):
    """Resolve URL and perform basic validation before fetching."""
    parsed = urllib.parse.urlparse(url)
    hostname = parsed.hostname
    port = parsed.port or (443 if parsed.scheme == 'https' else 80)

    # First resolution - check it's not internal
    try:
        addr = socket.getaddrinfo(hostname, port)[0][4][0]
    except socket.gaierror:
        raise ValueError(f"Cannot resolve {hostname}")

    # Block obvious private ranges (but not link-local thoroughly)
    if addr.startswith('10.') or addr.startswith('192.168.'):
        raise ValueError(f"Private IP blocked: {addr}")
    if addr.startswith('172.') and 16 <= int(addr.split('.')[1]) <= 31:
        raise ValueError(f"Private IP blocked: {addr}")
    if addr == '127.0.0.1':
        raise ValueError("Loopback blocked")

    return addr

def fetch_webhook_metadata(url, timeout=5):
    """Fetch webhook URL content after DNS validation passes."""
    # Time-of-check: DNS resolved to public IP above
    # Time-of-use: DNS may now resolve to 169.254.169.254 (IMDS)
    req = urllib.request.Request(url, headers={'User-Agent': 'StepFn-Validator/1.0'})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode('utf-8')

def store_result(execution_id, data):
    """Store fetched metadata in DynamoDB for workflow continuation."""
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table('workflow-webhook-results')
    table.put_item(Item={
        'execution_id': execution_id,
        'fetched_data': data[:4096],
        'timestamp': int(time.time())
    })

def lambda_handler(event, context):
    """Step Functions task: validate and fetch user webhook URL.

    Input from state machine:
    {
        "webhook_url": "https://example.com/hook",
        "execution_id": "arn:aws:states:..."
    }
    """
    webhook_url = event.get('webhook_url', '')
    execution_id = event.get('execution_id', context.aws_request_id)

    if not webhook_url:
        return {'statusCode': 400, 'error': 'Missing webhook_url'}

    # Validate URL scheme
    parsed = urllib.parse.urlparse(webhook_url)
    if parsed.scheme not in ('http', 'https'):
        return {'statusCode': 400, 'error': 'Invalid scheme'}

    # Validate hostname is not metadata endpoint directly
    if parsed.hostname in ('169.254.169.254', '169.254.170.2', 'metadata.google.internal'):
        return {'statusCode': 403, 'error': 'Metadata endpoint blocked'}

    try:
        # DNS check (TOCTOU vulnerable - attacker controls DNS TTL)
        resolved_ip = resolve_and_check(webhook_url)

        # Fetch happens AFTER check - DNS rebinding window
        # Attacker's DNS server returns public IP first, then 169.254.169.254
        content = fetch_webhook_metadata(webhook_url)

        # Store credentials/tokens if IMDS was reached
        store_result(execution_id, content)

        return {
            'statusCode': 200,
            'resolved_ip': resolved_ip,
            'content_length': len(content),
            'execution_id': execution_id
        }
    except ValueError as e:
        return {'statusCode': 403, 'error': str(e)}
    except Exception as e:
        return {'statusCode': 500, 'error': f'Fetch failed: {str(e)}'}
